buggyCode:
int firstBadVersion(int n) {
    int lo = 1, hi = n;
    while (lo < hi) {
        int mid = (lo + hi) / 2;
        if (isBadVersion(mid)) {
            hi = mid;          // mid lỗi: phiên bản đầu tiên ở mid hoặc trước đó
        } else {
            lo = mid + 1;      // mid tốt: phiên bản đầu tiên ở sau mid
        }
    }
    return lo;
}

fix.code:
int firstBadVersion(int n) {
    int lo = 1, hi = n;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;   // hoặc (lo + hi) >>> 1
        if (isBadVersion(mid)) {
            hi = mid;
        } else {
            lo = mid + 1;
        }
    }
    return lo;
}
// n = 2126753390 -> 1702766719 sau 31 lần gọi isBadVersion (đã chạy)
